    msg.alerta_tipo = data.estado === 'CRÍTICO' ? 'TEMP_CRÍTICA' : 'TEMP_ELEVADA';
    msg.alerta_msg  = (data.estado === 'CRÍTICO' ? '🔴' : '🟠') +
        ' Congelador A: ' + msg.temp + '°C — ' + data.estado;
    return [msg, msg];
}

