var setpoint   = msg.payload;
var congelador = msg.topic;   // 'A', 'B' o 'C'
var temp_actual = global.get('temp_' + congelador) || 0;

global.set('setpoint_' + congelador, setpoint);

var accion;
if (temp_actual > setpoint + 1) {
    accion = 'ENFRIAR';
} else if (temp_actual < setpoint - 1) {
    accion = 'CALENTAR';
} else {
    accion = 'MANTENER';
}

// Notificar el cambio de setpoint
var notifMsg = {
    alerta_tipo: 'SETPOINT',
    alerta_msg: '🎛 Congelador ' + congelador + ': setpoint ajustado a ' + setpoint + '°C — acción: ' + accion,
    congelador: congelador
};
node.send([msg, notifMsg]);

// Publicar comando vía MQTT hacia el simulador.py
msg.payload = { congelador: congelador, setpoint: setpoint, accion: accion };
msg.topic   = 'pesquera/congelador/' + congelador + '/control';
return null;

// Actualizar estado de este congelador en contexto global
var cong  = msg.congelador;
var temp  = msg.temp;
var hum   = msg.hum;
var esp   = msg.esp;
var est   = msg.estado;

var estado = global.get('cuarto_estado') || { A: null, B: null, C: null };
estado[cong] = { temp: temp, hum: hum, esp: esp, estado: est, hora: new Date().toTimeString().slice(0,8) };
global.set('cuarto_estado', estado);

// Determinar estado general del cuarto
var critico = false;
var alerta  = false;
['A','B','C'].forEach(function(c) {
    if (!estado[c]) return;
    if (estado[c].estado === 'CRÍTICO') critico = true;
    if (estado[c].estado === 'ALERTA')  alerta  = true;
});

var estadoGeneral = critico ? '🔴 CRÍTICO' : alerta ? '🟠 ALERTA' : '🟢 NORMAL';
var colorGeneral  = critico ? '#b91c1c'    : alerta  ? '#92400e'  : '#166534';
var bgGeneral     = critico ? '#fee2e2'    : alerta   ? '#fef3c7'  : '#dcfce7';

// Construir HTML del panel resumen
var html = '<div style="font-family:Segoe UI,sans-serif;padding:8px">';

// Banner de estado general
html += '<div style="background:' + bgGeneral + ';color:' + colorGeneral + ';';
html += 'border-radius:10px;padding:12px 20px;margin-bottom:12px;font-size:18px;font-weight:600;text-align:center">';
html += 'Estado General del Cuarto Frío: ' + estadoGeneral + '</div>';

// Tarjetas de cada congelador
html += '<div style="display:flex;gap:12px;flex-wrap:wrap">';
['A','B','C'].forEach(function(c) {
    var d = estado[c];
    if (!d) {
        html += '<div style="flex:1;min-width:200px;background:#f1f5f9;border-radius:10px;padding:14px">';
        html += '<div style="font-weight:600;color:#64748b">Congelador ' + c + '</div>';
        html += '<div style="color:#94a3b8;font-size:13px;margin-top:6px">Sin datos aún...</div></div>';
        return;
    }
    var bc = d.estado === 'CRÍTICO' ? '#fee2e2' : d.estado === 'ALERTA' ? '#fef3c7' : '#f0fdf4';
    var tc = d.estado === 'CRÍTICO' ? '#b91c1c' : d.estado === 'ALERTA' ? '#92400e' : '#166534';
    var em = d.estado === 'CRÍTICO' ? '🔴' : d.estado === 'ALERTA' ? '🟠' : '🟢';
    html += '<div style="flex:1;min-width:200px;background:' + bc + ';border-radius:10px;padding:14px;border:1px solid ' + tc + '33">';
    html += '<div style="font-weight:700;font-size:15px;color:' + tc + '">' + em + ' Congelador ' + c + '</div>';
    html += '<div style="margin-top:8px;font-size:13px;color:#334155">';
    html += '<div>🌡 <b>' + d.temp + ' °C</b></div>';
    html += '<div>💧 Humedad: ' + d.hum + '%</div>';
    html += '<div>🐟 Especie: ' + d.esp + '</div>';
    html += '<div style="color:#94a3b8;font-size:11px;margin-top:4px">Actualizado: ' + d.hora + '</div>';
    html += '</div></div>';
});
html += '</div></div>';

msg.payload = html;
return msg;

