var estado = msg.internet || global.get('internet_estado') || 'OK';
var color  = estado === 'OK' ? '#166534' : '#b91c1c';
var bg     = estado === 'OK' ? '#dcfce7' : '#fee2e2';
var texto  = estado === 'OK' ? '✅ Conexión activa' : '❌ Sin conexión';
